pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function testFuzz_property(address actor) public {
        // actor must be a non-contract, non-zero, non-caller EOA that never locked a guess
        vm.assume(actor != address(0));
        vm.assume(actor != address(this));
        vm.assume(actor.code.length == 0);

        bool ok = true;
        vm.prank(actor);
        try c.settle() {
            ok = true;
        } catch {
            ok = false;
        }

        // Reference: settle reverts for an address with no recorded guess block.
        // Mutant: the missing precondition is replaced by require(true), so settle proceeds without reverting.
        assertTrue(!ok);
    }
}
